-- Stage 4G.1. LOCAL ONLY. General enquiries are separate from project requests.
begin;
insert into public.permissions(code,description)values('enquiries.read','Read department-scoped general enquiries'),('enquiries.manage','Manage department-scoped general enquiries'),('enquiries.assess','Read and respond to explicitly shared technical briefs');
insert into public.role_permissions(role_id,permission_id)select r.id,p.id from public.roles r cross join public.permissions p where(p.code in('enquiries.read','enquiries.manage')and r.code in('platform_owner','operations_lead','content_community_lead'))or(p.code='enquiries.assess'and r.code in('platform_owner','technical_lead'));
create table business_private.contact_enquiries(id uuid primary key default gen_random_uuid(),reference text not null unique check(reference~'^BWEQ-[a-f0-9]{32}$'),full_name text not null,email text not null,whatsapp text,category text not null check(category in('general','partnership','collaboration','community','technical','other')),message text not null,department text not null check(department in('communications','operations')),status text not null default 'new'check(status in('new','in_progress','awaiting_response','resolved','closed')),version int not null default 1,idempotency_hash bytea not null unique,payload_hash bytea not null,duplicate_hash bytea not null,created_at timestamptz not null default now(),consent_version text not null check(consent_version='contact-v1'));
create index contact_duplicate on business_private.contact_enquiries(duplicate_hash,created_at);
create index contact_inbox on business_private.contact_enquiries(department,status,created_at desc);
create table business_private.enquiry_referrals(id uuid primary key default gen_random_uuid(),enquiry_id uuid not null references business_private.contact_enquiries(id)on delete restrict,brief text not null check(length(btrim(brief))between 1 and 3000),version int not null default 1,revoked_at timestamptz,created_by uuid references auth.users(id)on delete set null,created_at timestamptz not null default now());
create unique index enquiry_one_active_referral on business_private.enquiry_referrals(enquiry_id)where revoked_at is null;
create table business_private.enquiry_activity(id uuid primary key default gen_random_uuid(),enquiry_id uuid not null references business_private.contact_enquiries(id)on delete restrict,referral_id uuid references business_private.enquiry_referrals(id)on delete restrict,kind text not null check(kind in('status','routing','note','manual_email','manual_whatsapp','needs_follow_up','referral','referral_revoked','assessment')),body text not null check(length(body)<=4000),actor_id uuid references auth.users(id)on delete set null,operation_id uuid not null unique,payload jsonb not null,created_at timestamptz not null default now());
create index enquiry_history on business_private.enquiry_activity(enquiry_id,created_at);
create table business_private.enquiry_buckets(key_hash bytea not null,window_start timestamptz not null,attempts int not null check(attempts>0),primary key(key_hash,window_start));
revoke all on business_private.contact_enquiries,business_private.enquiry_referrals,business_private.enquiry_activity,business_private.enquiry_buckets from public,anon,authenticated,service_role;
create function business_private.enquiry_department()returns text language sql stable security definer set search_path=''as $$select case when exists(select from public.team_role_assignments a join public.roles r on r.id=a.role_id where a.user_id=auth.uid()and r.code='platform_owner')then'all'when exists(select from public.team_role_assignments a join public.roles r on r.id=a.role_id where a.user_id=auth.uid()and r.code='operations_lead')then'operations'when exists(select from public.team_role_assignments a join public.roles r on r.id=a.role_id where a.user_id=auth.uid()and r.code='content_community_lead')then'communications'end$$;
create function business_private.enquiry_access(p_id uuid,p_manage boolean default false)returns boolean language sql stable security definer set search_path=''as $$select app_private.has_aal2_session()and app_private.has_permission(case when p_manage then'enquiries.manage'else'enquiries.read'end)and exists(select from business_private.contact_enquiries e where e.id=p_id and(business_private.enquiry_department()='all'or e.department=business_private.enquiry_department()))$$;
do $$declare t text;begin foreach t in array array['contact_enquiries','enquiry_referrals','enquiry_activity','enquiry_buckets']loop execute format('alter table business_private.%I enable row level security',t);execute format('create policy %I on business_private.%I as restrictive for all to authenticated using((select app_private.has_aal2_session()))with check((select app_private.has_aal2_session()))',t||'_mfa',t);end loop;end;$$;
-- No direct table grants. These row policies additionally document the scope for future reviewed access.
create policy enquiry_scoped_read on business_private.contact_enquiries for select to authenticated using(business_private.enquiry_access(id));
create function public.submit_contact_enquiry(p_payload jsonb,p_reference text,p_key text,p_hash text,p_duplicate text,p_global text,p_email text)returns void language plpgsql security definer set search_path=''as $$declare old business_private.contact_enquiries;n int;k text;begin
 if p_payload is null or jsonb_typeof(p_payload)<>'object'or not(p_payload?'fullName'and p_payload?'email'and p_payload?'category'and p_payload?'message'and p_payload?'whatsapp'and p_payload?'consentVersion')or(p_payload-array['fullName','email','whatsapp','category','message','consentVersion'])<>'{}'::jsonb or not business_private.project_text(p_payload->>'fullName',1,160)or not business_private.project_text(p_payload->>'message',10,8000)or(p_payload->>'category')not in('general','partnership','collaboration','community','technical','other')or p_payload->>'category'is null or p_payload->>'consentVersion'is distinct from'contact-v1'or p_payload->>'email'is null or length(p_payload->>'email')>254 or(p_payload->>'email')<>lower(btrim(p_payload->>'email'))or(p_payload->>'email')!~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'or(p_payload->>'whatsapp'is not null and(p_payload->>'whatsapp')!~'^\+[1-9][0-9]{6,14}$')or p_reference is null or p_reference!~'^BWEQ-[a-f0-9]{32}$'then raise exception'Invalid contact submission'using errcode='22023';end if;
 foreach k in array array[p_key,p_hash,p_duplicate,p_global,p_email]loop if k is null or k!~'^[a-f0-9]{64}$'then raise exception'Invalid contact credential';end if;end loop;
 perform pg_advisory_xact_lock(42048,1);
 select * into old from business_private.contact_enquiries where idempotency_hash=decode(p_key,'hex');if found then if old.payload_hash<>decode(p_hash,'hex')then raise exception'Idempotency conflict'using errcode='PT409';end if;return;end if;
 foreach k in array array[p_global,p_email]loop insert into business_private.enquiry_buckets(key_hash,window_start,attempts)values(decode(k,'hex'),date_trunc('hour',clock_timestamp()),1)on conflict(key_hash,window_start)do update set attempts=business_private.enquiry_buckets.attempts+1 where business_private.enquiry_buckets.attempts<case when k=p_global then 100 else 3 end returning attempts into n;if n is null then raise exception'Contact unavailable';end if;end loop;
 if exists(select from business_private.contact_enquiries where duplicate_hash=decode(p_duplicate,'hex')and created_at>now()-interval'24 hours')then return;end if;
 insert into business_private.contact_enquiries(reference,full_name,email,whatsapp,category,message,department,idempotency_hash,payload_hash,duplicate_hash,consent_version)values(p_reference,p_payload->>'fullName',p_payload->>'email',p_payload->>'whatsapp',p_payload->>'category',p_payload->>'message',case when p_payload->>'category'in('partnership','collaboration')then'operations'else'communications'end,decode(p_key,'hex'),decode(p_hash,'hex'),decode(p_duplicate,'hex'),'contact-v1');
end;$$;
create function public.list_contact_enquiries(p_status text default null,p_reference text default null)returns jsonb language plpgsql stable security definer set search_path=''as $$begin perform business_private.require_permission('enquiries.read');if p_status is not null and p_status not in('new','in_progress','awaiting_response','resolved','closed')or p_reference is not null and p_reference!~'^BWEQ-[a-f0-9]{32}$'then raise exception'Invalid filter';end if;return(select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb)from(select e.id,e.reference,e.full_name,e.category,e.department,e.status,e.version,e.created_at from business_private.contact_enquiries e where business_private.enquiry_access(e.id)and(p_status is null or e.status=p_status)and(p_reference is null or e.reference=p_reference)order by e.created_at desc,e.id limit 100)x);end;$$;
create function public.get_contact_enquiry(p_id uuid)returns jsonb language plpgsql stable security definer set search_path=''as $$declare e business_private.contact_enquiries;begin if not business_private.enquiry_access(p_id)then raise exception'Access denied'using errcode='42501';end if;select * into e from business_private.contact_enquiries where id=p_id;return jsonb_build_object('id',e.id,'reference',e.reference,'fullName',e.full_name,'email',e.email,'whatsapp',e.whatsapp,'category',e.category,'message',e.message,'department',e.department,'status',e.status,'version',e.version,'createdAt',e.created_at,'history',(select coalesce(jsonb_agg(jsonb_build_object('kind',kind,'body',body,'at',created_at)order by created_at,id),'[]'::jsonb)from business_private.enquiry_activity where enquiry_id=e.id),'referrals',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'brief',brief,'version',version,'revoked',revoked_at is not null,'at',created_at)order by created_at),'[]'::jsonb)from business_private.enquiry_referrals where enquiry_id=e.id));end;$$;
-- A shared operation UUID is an idempotency key; reusing it with another payload/actor is rejected.
create function public.manage_contact_enquiry(p_id uuid,p_version int,p_operation uuid,p_action text,p_value text,p_body text)returns void language plpgsql security definer set search_path=''as $$declare e business_private.contact_enquiries;prior business_private.enquiry_activity;payload jsonb:=jsonb_build_object('id',p_id,'action',p_action,'value',p_value,'body',p_body);kind text;rid uuid;begin
 if not business_private.enquiry_access(p_id,true)then raise exception'Access denied'using errcode='42501';end if;select * into e from business_private.contact_enquiries where id=p_id for update;
 select * into prior from business_private.enquiry_activity where operation_id=p_operation;if found then if prior.actor_id=auth.uid()and prior.payload=payload then return;end if;raise exception'Operation conflict'using errcode='PT409';end if;
 if e.version is distinct from p_version then raise exception'Enquiry changed'using errcode='PT409';end if;if p_operation is null or not business_private.project_text(p_body,1,3000)then raise exception'Action note required';end if;
 if p_action='status'then if p_value is null or p_value not in('new','in_progress','awaiting_response','resolved','closed')or not(case e.status when'new'then p_value in('in_progress','closed')when'in_progress'then p_value in('awaiting_response','resolved','closed')when'awaiting_response'then p_value in('in_progress','resolved','closed')when'resolved'then p_value in('in_progress','closed')when'closed'then p_value='in_progress'else false end)then raise exception'Invalid transition';end if;update business_private.contact_enquiries set status=p_value where id=p_id;kind:='status';
 elsif p_action='route'then if p_value is null or p_value not in('communications','operations')or p_value=e.department then raise exception'Invalid routing';end if;update business_private.contact_enquiries set department=p_value where id=p_id;kind:='routing';
 elsif p_action='refer'then if p_value is distinct from'technology'then raise exception'Invalid assessment target';end if;insert into business_private.enquiry_referrals(enquiry_id,brief,created_by)values(p_id,p_body,auth.uid())returning id into rid;kind:='referral';
 elsif p_action='revoke'then update business_private.enquiry_referrals set revoked_at=now(),version=version+1 where enquiry_id=p_id and id::text=p_value and revoked_at is null returning id into rid;if not found then raise exception'Active referral unavailable';end if;kind:='referral_revoked';
 elsif p_action in('note','manual_email','manual_whatsapp','needs_follow_up')then if p_value is distinct from''then raise exception'Unexpected action value';end if;if p_action='manual_whatsapp'and e.whatsapp is null then raise exception'No submitted WhatsApp contact';end if;kind:=p_action;
 else raise exception'Invalid action';end if;
 update business_private.contact_enquiries set version=version+1 where id=p_id;
 insert into business_private.enquiry_activity(enquiry_id,referral_id,kind,body,actor_id,operation_id,payload)values(p_id,rid,kind,case when kind in('routing','status')then p_value||': '||p_body else p_body end,auth.uid(),p_operation,payload);
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,metadata)values(auth.uid(),'enquiry.'||kind,'contact_enquiry',p_id::text,jsonb_build_object('operationId',p_operation));
end;$$;
create function public.list_enquiry_assessments()returns jsonb language plpgsql stable security definer set search_path=''as $$begin perform business_private.require_permission('enquiries.assess');return(select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'brief',r.brief,'version',r.version,'createdAt',r.created_at,'responses',(select coalesce(jsonb_agg(jsonb_build_object('body',a.body,'at',a.created_at)order by a.created_at),'[]'::jsonb)from business_private.enquiry_activity a where a.referral_id=r.id and a.kind='assessment'))order by r.created_at),'[]'::jsonb)from business_private.enquiry_referrals r where r.revoked_at is null);end;$$;
create function public.respond_enquiry_assessment(p_id uuid,p_version int,p_operation uuid,p_body text)returns void language plpgsql security definer set search_path=''as $$declare r business_private.enquiry_referrals;prior business_private.enquiry_activity;payload jsonb:=jsonb_build_object('id',p_id,'body',p_body);begin perform business_private.require_permission('enquiries.assess');select * into r from business_private.enquiry_referrals where id=p_id and revoked_at is null for update;if not found then raise exception'Active assessment unavailable'using errcode='42501';end if;select * into prior from business_private.enquiry_activity where operation_id=p_operation;if found then if prior.actor_id=auth.uid()and prior.payload=payload then return;end if;raise exception'Operation conflict'using errcode='PT409';end if;if r.version is distinct from p_version then raise exception'Assessment changed'using errcode='PT409';end if;if p_operation is null or not business_private.project_text(p_body,1,3000)then raise exception'Assessment required';end if;insert into business_private.enquiry_activity(enquiry_id,referral_id,kind,body,actor_id,operation_id,payload)values(r.enquiry_id,r.id,'assessment',p_body,auth.uid(),p_operation,payload);update business_private.enquiry_referrals set version=version+1 where id=p_id;insert into public.audit_logs(actor_id,action,resource_type,resource_id)values(auth.uid(),'enquiry.assessment','enquiry_referral',p_id::text);end;$$;
do $$declare f record;begin for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where(n.nspname='business_private'and p.proname in('enquiry_department','enquiry_access'))or(n.nspname='public'and p.proname in('submit_contact_enquiry','list_contact_enquiries','get_contact_enquiry','manage_contact_enquiry','list_enquiry_assessments','respond_enquiry_assessment'))loop execute format('revoke all on function %s from public,anon,authenticated,service_role',f.sig);end loop;end;$$;
grant execute on function public.submit_contact_enquiry(jsonb,text,text,text,text,text,text)to service_role;
grant execute on function public.list_contact_enquiries(text,text),public.get_contact_enquiry(uuid),public.manage_contact_enquiry(uuid,int,uuid,text,text,text),public.list_enquiry_assessments(),public.respond_enquiry_assessment(uuid,int,uuid,text)to authenticated;
commit;
